.aznet-theme-homepage-hero-library__fieldset {
    min-width: 0;
    margin: 16px 0;
    padding: 0;
    border: 0;
}
.aznet-theme-homepage-hero-library__grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    margin: 0;
}
.aznet-theme-homepage-hero-library__card {
    display: grid;
    gap: 9px;
    padding: 12px;
    border: 1px solid #c3c4c7;
    border-radius: 8px;
    background: #fff;
    cursor: pointer;
}
.aznet-theme-homepage-hero-library__card:has(input:checked) {
    border-color: #3858e9;
    box-shadow: 0 0 0 1px #3858e9;
}
.aznet-theme-homepage-hero-library__card input {
    margin: 0;
}
.aznet-theme-homepage-hero-library__preview {
    display: grid;
    grid-template-columns: 46% 54%;
    gap: 5px;
    min-height: 76px;
    padding: 8px;
    border-radius: 6px;
    background: #f0f0f1;
}
.aznet-theme-homepage-hero-library__preview span {
    display: block;
    border-radius: 4px;
    background: #dcdcde;
}
.aznet-theme-homepage-hero-library__preview span:last-child {
    background: #c3c4c7;
}
.aznet-theme-homepage-hero-library__card--centered .aznet-theme-homepage-hero-library__preview {
    grid-template-columns: 1fr;
    padding-inline: 25%;
}
.aznet-theme-homepage-hero-library__card--centered .aznet-theme-homepage-hero-library__preview span:last-child {
    display: none;
}
.aznet-theme-homepage-hero-library__card--inverse .aznet-theme-homepage-hero-library__preview {
    background: #3f1f27;
}
.aznet-theme-homepage-hero-library__card--inverse .aznet-theme-homepage-hero-library__preview span {
    background: #e7d8b2;
}
.aznet-theme-homepage-hero-library__card--media-left .aznet-theme-homepage-hero-library__preview span:first-child {
    order: 2;
}
.aznet-theme-homepage-hero-library__card--media-left .aznet-theme-homepage-hero-library__preview span:last-child {
    order: 1;
}
@media (max-width: 1100px) {
    .aznet-theme-homepage-hero-library__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 782px) {
    .aznet-theme-homepage-hero-library__grid { grid-template-columns: 1fr; }
}

