/* D-040 / TD1 Template Library */
.aznet-theme-template-library{margin:14px 0 18px}
.aznet-theme-template-library__toolbar{display:grid;grid-template-columns:minmax(220px,1fr) minmax(180px,260px);gap:12px;margin-bottom:16px}
.aznet-theme-template-library__toolbar label{display:grid;gap:6px;font-weight:600}
.aznet-theme-template-library__toolbar input,.aznet-theme-template-library__toolbar select{width:100%;max-width:none}
.aznet-theme-template-library__fieldset{min-width:0;margin:0;padding:0;border:0}
.aznet-theme-template-library__grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}
.aznet-theme-template-library__card{display:grid;grid-template-rows:auto 1fr;gap:10px;position:relative;padding:12px;border:1px solid #c3c4c7;border-radius:10px;background:#fff;cursor:pointer}
.aznet-theme-template-library__card:hover{border-color:#8c8f94}
.aznet-theme-template-library__card:has(input:checked){border-color:#3858e9;box-shadow:0 0 0 1px #3858e9}
.aznet-theme-template-library__card>input{position:absolute;top:12px;right:12px;margin:0}
.aznet-theme-template-library__preview{display:grid;grid-template-columns:1.2fr .8fr;grid-template-rows:52px 34px;gap:6px;min-height:98px;padding:10px;border-radius:8px;background:#f0f0f1}
.aznet-theme-template-library__preview span{display:block;border-radius:4px;background:#dcdcde}
.aznet-theme-template-library__preview span:first-child{grid-row:1/3}
.aznet-theme-template-library__preview--law-01{background:#f4eef0}
.aznet-theme-template-library__preview--law-01 span:first-child{background:#4d1628}
.aznet-theme-template-library__preview--law-01 span:nth-child(2){background:#c8a96b}
.aznet-theme-template-library__preview--curtain-01{background:#f3eee7}
.aznet-theme-template-library__preview--curtain-01 span:first-child{background:#9a7655}
.aznet-theme-template-library__preview--curtain-01 span:nth-child(2){background:#d9c8b5}
.aznet-theme-template-library__meta{display:grid;gap:5px}
.aznet-theme-template-library__meta strong{font-size:15px}
.aznet-theme-template-library__category{color:#646970;font-size:12px}
.aznet-theme-template-library__state{width:max-content;margin-top:3px;padding:3px 7px;border-radius:999px;background:#edfaef;color:#116329;font-size:11px;font-weight:600}
.aznet-theme-template-library__off{display:flex;align-items:center;gap:7px;margin:16px 0 8px}
.aznet-theme-template-library__empty{display:none;margin:12px 0;color:#646970}
.aznet-theme-template-library__card[hidden]{display:none}
@media(max-width:782px){.aznet-theme-template-library__toolbar{grid-template-columns:1fr}.aznet-theme-template-library__grid{grid-template-columns:1fr}}


/* Homepage Map shared-model primary authoring */
.aznet-theme-homepage-map{margin-top:20px}
.aznet-theme-homepage-map__intro{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}
.aznet-theme-homepage-map__intro h2{margin:0 0 6px}
.aznet-theme-homepage-map__utilities{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:flex-end}
.aznet-theme-homepage-map__preset{display:inline-flex;align-items:center;min-height:32px;padding:0 10px;border:1px solid #dcdcde;border-radius:999px;background:#fff;font-weight:600}
.aznet-theme-homepage-map__list{display:grid;gap:16px}
.aznet-theme-homepage-map__card{display:grid;gap:12px;padding:18px;border:1px solid #dcdcde;border-radius:10px;background:#fff}
.aznet-theme-homepage-map__heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.aznet-theme-homepage-map__heading h3{margin:0;font-size:16px}
.aznet-theme-homepage-map__position{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:999px;background:#f0f0f1;font-weight:600}
.aznet-theme-homepage-map__status{display:inline-flex;align-items:center;gap:6px;margin-left:auto;padding:5px 9px;border:1px solid #a9ddbc;border-radius:999px;background:#dff3e7;color:#116b3a;font-size:12px;font-weight:600}
.aznet-theme-homepage-map__title{font-size:15px}
.aznet-theme-homepage-map__summary,.aznet-theme-homepage-map__source{margin:0}
.aznet-theme-homepage-map__source{color:#646970}
.aznet-theme-homepage-map__items{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:6px 16px;margin:0;padding-left:20px}
.aznet-theme-homepage-map__actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.aznet-theme-homepage-map__actions .button{min-height:44px;display:inline-flex;align-items:center}
.aznet-theme-homepage-map__details{padding-top:10px;border-top:1px solid #f0f0f1}
.aznet-theme-homepage-map__details>summary{cursor:pointer;font-weight:600;min-height:44px;display:flex;align-items:center}
