/* Site-wide Law 01 Header presentation.
 * WordPress continues to own site identity, menus, search and mapped Contact Page data.
 */

.aznet-theme-site-header--law01-burgundy-gold {
    --law01-client-burgundy: #7a0e18;
    --law01-client-burgundy-deep: #560912;
    --law01-brand-red: #8f111b;
    --aznet-theme-header-muted: #6f675f;
    --aznet-theme-header-border: rgba(143, 17, 27, .14);
    border-bottom: 1px solid rgba(143, 17, 27, .12);
    background: rgba(255, 253, 248, .98);
    color: #241d19;
    box-shadow: 0 .35rem 1.4rem rgba(68, 42, 26, .055);
    backdrop-filter: blur(12px);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__inner {
    width: min(calc(100% - (2 * var(--aznet-theme-gutter))), 96rem);
    min-height: 88px;
    gap: clamp(.8rem, 1.3vw, 1.5rem);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__brand {
    gap: .8rem;
    color: var(--law01-brand-red);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__logo {
    width: 64px;
    max-width: 64px;
    max-height: 64px;
    flex: 0 0 64px;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__brand-copy {
    display: grid;
    max-width: 17rem;
    gap: .12rem;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__brand-title {
    display: block;
    max-width: none;
    color: var(--law01-brand-red);
    font-family: var(--aznet-theme-font-family-heading);
    font-size: clamp(1.05rem, 1.55vw, 1.4rem);
    font-weight: var(--aznet-theme-font-weight-bold);
    line-height: 1.15;
    text-transform: uppercase;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__brand-kicker {
    color: #39332d;
    font-size: .78rem;
    font-weight: var(--aznet-theme-font-weight-semibold);
    letter-spacing: .09em;
    line-height: 1.2;
    text-transform: uppercase;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu {
    gap: clamp(.75rem, 1.3vw, 1.4rem);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu a {
    color: #2c241f;
    font-size: 1rem;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu > .current-menu-item > a,
.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu > .current_page_item > a {
    position: relative;
    color: var(--law01-brand-red);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu > .current-menu-item > a::after,
.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu > .current_page_item > a::after {
    position: absolute;
    right: 0;
    bottom: .1rem;
    left: 0;
    height: 2px;
    background: var(--law01-brand-red);
    content: "";
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu a:hover,
.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__menu a:focus-visible,
.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__utility:hover,
.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__utility:focus-visible {
    color: var(--law01-brand-red);
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__search {
    border-color: rgba(143, 17, 27, .2);
    background: #fff;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__search input[type="search"] {
    color: #2c241f;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__search input[type="search"]::placeholder {
    color: #6f675f;
}

.aznet-theme-site-header--law01-burgundy-gold .aznet-theme-site-header__search button {
    position: relative;
    width: 2.4rem;
    min-width: 2.4rem;
    padding: 0;
    border-left-color: rgba(143, 17, 27, .2);
    color: var(--law01-brand-red);
